import express from "express";
import auth from "../../middlewares/auth";
import { mealControllers } from "./meal.controller";
import { UserRole } from "@prisma/client";

const router = express.Router();

router.post("/create-meal", auth(), mealControllers.createMeal);
router.post("/auto-generate/plan", auth(), mealControllers.autogeneratePlan);
router.post("/create-today/meal-plan", auth(), mealControllers.createMealPlan);
router.post(
  "/auto-generated/meal-plan",
  auth(),
  mealControllers.autogeneratedMealPlan
);
router.get("/my-plans", auth(), mealControllers.myMealPlans);
router.get("/get-meals", mealControllers.getMeals);
router.patch("/:mealId", auth(UserRole.ADMIN), mealControllers.updateMeal);
router.delete("/:mealId", auth(UserRole.ADMIN), mealControllers.deleteMeal);
router.get("/:mealId", auth(), mealControllers.singleMeal);
router.get("/details/:mealId", auth(), mealControllers.mealDetails);
router.get(
  "/generated/meals",
  auth(UserRole.ADMIN),
  mealControllers.generatedMeals
);
router.patch(
  "/update/:mealId",
  auth(UserRole.ADMIN),
  mealControllers.updateGeneratedMeal
);
router.delete(
  "/delete/:mealId",
  auth(UserRole.ADMIN),
  mealControllers.deleteGeneratedMeal
);
router.get(
  "/generated/details/:mealId",
  auth(UserRole.ADMIN),
  mealControllers.generatedMealDetails
);
router.get("/my/plan-info", auth(), mealControllers.myPlanInfo);

export const mealRoutes = router;
